
function animateLetters(){
    var letters = document.querySelectorAll(".letter-outline-e, .letter-outline-i")
    console.log(letters)
    

    var css = "",
    head = document.head || document.getElementsByTagName('head')[0],
    style = document.createElement('style');
    style.type = 'text/css';
    
    for (var i = 0; i < letters.length; i ++){
        var myPath = letters[i];
        var length = myPath.getTotalLength();
    
        myPath.classList.add('letter-outline-visible') 
        myPath.classList.add('letter-outline-' + i)
        css += ` .letter-outline-${i}{ stroke-dasharray:${length}; stroke-dashoffset:${length};}`
    }

    style.appendChild(document.createTextNode(css));
    head.appendChild(style);



}
animateLetters();


